import openpyxl

wb=openpyxl.load_workbook('/root/weoapr2025all.xlsx', read_only=True)
ws=wb.active
header = ws.cell(1,1).value.split('\t')
# clean header
# remove trailing empty header entries
while header and header[-1]=='':
    header.pop()

idx = {h:i for i,h in enumerate(header)}

# check year columns
print('header len', len(header), 'year 2000 idx', idx.get('2000'))

geo = {}
for row in ws.iter_rows(min_row=3, values_only=True):
    line = row[0]
    if not line:
        continue
    parts = line.split('\t')
    # pad
    if len(parts) < len(header):
        parts += ['']*(len(header)-len(parts))
    country = parts[idx['Country']]
    if country != 'Georgia':
        continue
    code = parts[idx['WEO Subject Code']]
    if code in ('NGDP_R','NGDP_RPCH'):
        geo[code]=parts
    if len(geo)==2:
        break

print('found', geo.keys())
for code, parts in geo.items():
    # extract years
    data={}
    for year in range(2000,2028):
        val = parts[idx[str(year)]] if str(year) in idx else ''
        data[year]=val
    print(code, list(data.items())[:5], list(data.items())[-4:])
PY"}

